import{_ as o,o as e,c as n,a0 as r}from"./chunks/framework.DsVhn5Vy.js";const c=JSON.parse('{"title":"第 16 章 · 综合实战：完成一次可解释的优化","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/ch16.md","filePath":"chapters/ch16.md"}'),s={name:"chapters/ch16.md"};function d(a,t,i,l,p,h){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="第-16-章-·-综合实战-完成一次可解释的优化" tabindex="-1">第 16 章 · 综合实战：完成一次可解释的优化 <a class="header-anchor" href="#第-16-章-·-综合实战-完成一次可解释的优化" aria-label="Permalink to &quot;第 16 章 · 综合实战：完成一次可解释的优化&quot;">​</a></h1><p>全书的方法在这里收拢成一次完整的实战：<strong>固定目标 → 建立基线 → 有证据的瓶颈判断 → 已学机制改动 → 分别复测再验证组合 → 无收益则解释并撤回 → 完整报告</strong>。负载选在第 1 章教学服务同栈（Qwen3-0.6B + transformers，CPU 进程内）的多轮问答——它足够真实（每一步都是实测），又足够小（十几分钟一个闭环），把&quot;独立运行、讲清原理、定位问题、保护正确性、复现结论&quot;全部走一遍（16 章验收原文）。</p><p>实验 <code>experiments/exp_ch16_capstone/</code>（全部本机实测）。文本服务读者到这就收官；第 13/14 章的负载换汤不换药——阶段诊断（13.4）与成本账（14.2）就是 VLM/视频版的&quot;固定目标与瓶颈判断&quot;。</p><h2 id="_16-1-固定目标-资源、质量与服务-先于一切测量" tabindex="-1">16.1 固定目标：资源、质量与服务（先于一切测量） <a class="header-anchor" href="#_16-1-固定目标-资源、质量与服务-先于一切测量" aria-label="Permalink to &quot;16.1 固定目标：资源、质量与服务（先于一切测量）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>固定值</th><th>依据</th></tr></thead><tbody><tr><td>负载</td><td>8 会话 × 3 轮（原问题→一句话总结→再举例），第 5 章 8 样例</td><td>多轮历史使 prefill 随轮次增长</td></tr><tr><td>生成口径</td><td>greedy、直答模式（enable_thinking=False）、每轮 ≤24 token</td><td>复现友好；护栏非调优对象</td></tr><tr><td>资源</td><td>本机 CPU 单进程；fp32 ≈1.4GB / int8 ≈0.37GB 权重</td><td>第 5 章口径</td></tr><tr><td>质量</td><td>第 1 轮答案任务预算 <strong>≥7/8</strong>（第 5 章同判据）</td><td>预算层是判定层</td></tr><tr><td>正确性</td><td>复用结构契约（cache_miss==0，断言）+ 逐 token 对照 + 任务预算判定</td><td>第 5 章三层验收</td></tr><tr><td>服务</td><td>轮次 TTFT p95 相对基线改善 <strong>≥20%</strong>；ITL 均值（≈TPOT）作观察记录不设线（单会话串行闭环，无并发吞吐目标）</td><td>本机无 GPU，取相对目标</td></tr></tbody></table><p>会话构造有一个实测撞见的模板事实：Qwen3 直答模式把空 <code>&lt;think&gt;</code> 块放进生成头，但<strong>历史重渲染不含它</strong>——逐轮重新渲染对话与本轮实际消费的 token 序列必然分叉，跨轮前缀复用会 100% 落空（开发期 16/16 miss 的实证）。因此实验采用 <strong>token 级增量构造</strong>（会话 token 序列逐轮延长，与引擎按 token 前缀做前缀缓存同一语义）——这个坑本身就是部署多轮服务时要写给后端的契约：<strong>要么发 token 级增量，要么接受模板重渲染吃掉前缀命中</strong>。</p><h2 id="_16-2-基线与瓶颈判断-证据先行" tabindex="-1">16.2 基线与瓶颈判断：证据先行 <a class="header-anchor" href="#_16-2-基线与瓶颈判断-证据先行" aria-label="Permalink to &quot;16.2 基线与瓶颈判断：证据先行&quot;">​</a></h2><p>基线 = 第 1 章服务的语义（每请求重发完整历史、全新缓存）。逐轮实测（8 会话 24 轮）：</p><ul><li><strong>TTFT 随轮次增长</strong>：会话越长，每轮 prefill 重算的 token 越多——基线实喂 1,534 token，而会话净内容只有 561 token（v2 证实：每 token 只需喂一次）——<strong>63% 的实喂量是重复计算</strong>；</li><li><strong>decode 与轮次无关</strong>：每轮 24 token 上限，逐步成本恒定（ITL 均值 ≈34ms，即本负载的 TPOT 观察值）；</li><li>总墙钟 39.3s（TTFT 段 9.4s 占 24%、decode 段 29.9s 占 76%）、TTFT p50/p95 = 377/709ms、质量 8/8。</li></ul><p>证据指向的瓶颈是<strong>重复 prefill</strong>（第 3 章方法的结论：时间线拆开看哪段随负载增长），不是算子执行——所以改动选&quot;消重复&quot;而不是执行层优化。profiler 采集（3.5 方法）本章未取：逐轮时间线分解已足以定位阶段占比，留作扩展并如实声明。</p><h2 id="_16-3-改动、复测与组合-一项通过、一项撤回" tabindex="-1">16.3 改动、复测与组合：一项通过、一项撤回 <a class="header-anchor" href="#_16-3-改动、复测与组合-一项通过、一项撤回" aria-label="Permalink to &quot;16.3 改动、复测与组合：一项通过、一项撤回&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变体</th><th>总墙钟</th><th>TTFT p50/p95</th><th>实喂/净内容 token</th><th>质量</th><th>轨迹对照</th><th>判定</th></tr></thead><tbody><tr><td>baseline</td><td>39.3s</td><td>377/709ms</td><td>1534/561</td><td>8/8</td><td>—</td><td>基线</td></tr><tr><td>v1 int8</td><td>39.1s</td><td>225/328ms</td><td>1586/561</td><td><strong>6/8</strong></td><td>分叉</td><td><strong>撤回</strong></td></tr><tr><td>v2 前缀 KV 复用</td><td><strong>31.7s</strong></td><td><strong>152/209ms</strong></td><td><strong>561/561</strong></td><td>8/8</td><td><strong>24/24 全同</strong></td><td><strong>采纳</strong></td></tr><tr><td>v1+v2</td><td>37.0s</td><td>138/171ms</td><td>563/561</td><td>6/8</td><td>vs v1 仅 9/24 同</td><td>不采纳</td></tr></tbody></table><p>（净内容 = 会话各 token 只喂一次的量，即 v2 的实喂数——基线实喂 1,534 中 973 是重复。）</p><p><strong>v2（第 4 章机制）通过</strong>：TTFT p95 <strong>−70.5%</strong>、实喂 token <strong>−63%</strong>（1,534→561，每轮只喂增量：上轮尾部 token + 新用户轮后缀）、总墙钟 <strong>−19.3%</strong>、质量 8/8 不变、结构契约（缓存长度==已消费序列、token 前缀精确衔接）断言全过；与基线 <strong>24/24 轮逐 token 全同</strong>——同一输入序列下，贪心复用路径在本负载未出现任何 argmax 翻转（累计 [1,S] 与单次 [1,L] 前向的浮点差异未越过并列点；如实报告为实测结果，不写成普遍保证）。最终脚本两次完整运行关键结论一致（v2 TTFT p95 改善 69.7%/70.5%、质量均 8/8、均 24/24 全同）。</p><p><strong>v1（第 5 章机制）撤回</strong>：TTFT p95 改善 53.8%（prefill 的 int8 GEMM 确实快）但<strong>质量 6/8 低于 7/8 预算</strong>，且总墙钟两次运行为 −0.5%/+5.7%（与基线持平、无稳定收益——decode 侧反量化开销吃掉 prefill 收益，第 5 章&quot;压缩格式≠内核收益&quot;的端到端版）。质量失败均为截断敏感：int8 扰动让开场变啰嗦，24 token 上限装不下要点（zh_qa_2 的&quot;散射&quot;没出现、code_1 的代码没输出）。按 16.3 如实撤回；作为内存受限备选保留（权重 3.84× 压缩），启用前须放宽 token 上限重验预算。<strong>组合</strong>：继承 v1 的质量失败，不采纳——最终配置 = <strong>v2 单独启用</strong>。组合与 v1 仅 9/24 全同：int8 数值噪声放大批形状差异的翻转（观察记录，raw.json 存档）。</p><p>这个过程就是&quot;无稳定收益时解释原因并撤回&quot;的完整示范：v1 不是坏改动（第 5 章里它过了预算——那边 token 上限 48），是<strong>本负载的质量预算下不合格</strong>——结论永远绑定在条件下。</p><h2 id="_16-4-报告-入口、环境、原始测量、改动、适用范围、回退" tabindex="-1">16.4 报告：入口、环境、原始测量、改动、适用范围、回退 <a class="header-anchor" href="#_16-4-报告-入口、环境、原始测量、改动、适用范围、回退" aria-label="Permalink to &quot;16.4 报告：入口、环境、原始测量、改动、适用范围、回退&quot;">​</a></h2><p>完整报告在 <code>experiments/exp_ch16_capstone/record.md</code>（含开发期三轮契约调试的过程记录——模板重渲染、基线只喂增量、尾部 token 双计数，每一版都如实保留），原始测量在 raw.json（逐轮 TTFT/ITL/答案/缓存状态/分叉标记）。要点：</p><ul><li><strong>入口</strong>：<code>python experiments/exp_ch16_capstone/run_capstone.py</code>（约 10–15 分钟）；</li><li><strong>环境</strong>：CPU 单进程，Qwen3-0.6B（c1899de2）fp32/int8；生成口径与全部固定值在脚本顶部常量；</li><li><strong>适用范围</strong>：结论限于&quot;CPU、多轮问答、24 token/轮、贪心直答&quot;口径；GPU/引擎下 TTFT 与 decode 占比不同，须按第 15 章容量方法重测再迁移；</li><li><strong>回退</strong>：v2 是纯运行时结构，关闭即回基线；v1 撤回即不部署，不改任何权重文件。</li></ul><h2 id="动手与验收" tabindex="-1">动手与验收 <a class="header-anchor" href="#动手与验收" aria-label="Permalink to &quot;动手与验收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在解压后的 pi-infer-labs 目录中执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/exp_ch16_capstone/run_capstone.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 四变体闭环 + 契约断言 + SLO 判定（全部实测）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>验收对照基准条款：固定资源/质量/服务目标（16.1 表，先于基线）；用前文代码与记录建立基线并提出有证据的瓶颈判断（16.2：逐轮时间线，重复 prefill 占实喂 52%）；完成一至两项已学机制改动、分别复测再验证组合（16.3 表）；无稳定收益时解释原因并撤回（v1 与组合的处置）；提交入口/环境与输入/原始测量/改动与结果/适用范围/回退方法（16.4 与 record.md）。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><p><strong>练习 1</strong>：为什么质量预算锚定第 1 轮而不是三轮全部？答：第 1 轮是任务事实（答案要点明确、判据可锚定第 5 章样例）；第 2/3 轮是开放式总结/举例——没有唯一正确答案，只能观察。预算设在可判定的层，是第 5 章&quot;任务层预算&quot;原则的运用；三轮答案仍全部存档供检视。</p><p><strong>练习 2</strong>：v2 的 TTFT 段总量下降 60%（9.4→3.8s），总墙钟只下降 19.3%，为什么？答：总墙钟 = TTFT 段 + decode 段，基线里 TTFT 只占 24%、decode 占 76%——复用消除的是 prefill 重复，decode 一 token 没少：TTFT 段 −5.6s 贡献约 14 个百分点，其余 5 个百分点来自 decode 段 −6.7%（本机单次运行的波动范围内，decode 并未做任何改动，如实归为噪声）。要压 decode 得走投机解码（第 7 章）或更强算力/内核；<strong>优化收益的上限由它作用的阶段占比决定</strong>（第 3 章时间线拆解的逆用）。</p><p><strong>练习 3</strong>：本实验复用与基线 24/24 全同，为什么仍把&quot;逐 token 全等&quot;放在观察层而不是判定层？答：两条路径的计算批形状不同（单次 [1,L] vs 累计 [1,S] 前向），浮点差异原则上可能翻转近并列的 argmax——本负载实测没有翻转，但这不是可断言的保证（组合变体里 int8 就翻了 15/24）。可断言的判定层是结构契约（缓存长度/前缀衔接）与任务预算；轨迹层如实记录。开发期的教训反过来更值钱：<strong>发现分叉先排除输入序列不等</strong>——第二版实现的历史双计数 bug 曾被误释为&quot;浮点差异&quot;，修复后分叉消失（record 过程记录）。</p><p><strong>练习 4</strong>：把本实验搬到 vLLM（第 15 章环境），v2 对应什么？还要自己实现吗？答：对应 <code>--enable-prefix-caching</code>（默认开）——引擎按 token 前缀块级命中自动完成；自己要做的反而是把&quot;模板重渲染吃掉命中&quot;的坑避掉（token 级增量构造，或确认模板行为）。这正说明机制章（第 4 章）与部署章（第 15 章）的关系：<strong>理解机制才能正确使用引擎的开关</strong>。</p><p><strong>练习 5</strong>：v1 在第 5 章过了预算（7/8），在这里没过（6/8），矛盾吗？答：不矛盾——预算通过与否绑定条件：那边 token 上限 48、样例判据相同；这边 24 上限更紧，int8 扰动让开场变长就截断了要点。实验报告必须把条件写全（生成口径/上限/判据），&quot;某优化过了质量预算&quot;永远是&quot;在某条件下过了&quot;。</p><p><strong>练习 6</strong>：给出本闭环的回退步骤与验证方法。答：v2 关闭会话缓存即回基线（纯运行时结构，无状态残留）——验证：重跑基线一遍数字应复现（贪心确定性）；v1 撤回即不部署（quantize_dynamic 不改源权重文件）——验证：重新加载 fp32 模型跑基线。回退的验证与改动的验证同一判据：<strong>能回到已知的基线状态，才算真正掌控了改动</strong>。</p><h2 id="小结-算了什么、慢在哪里、怎样验证" tabindex="-1">小结：算了什么、慢在哪里、怎样验证 <a class="header-anchor" href="#小结-算了什么、慢在哪里、怎样验证" aria-label="Permalink to &quot;小结：算了什么、慢在哪里、怎样验证&quot;">​</a></h2><ul><li>目标先于测量：负载/口径/资源/质量预算/服务目标全部固定后再跑基线——结论才有条件可绑定；</li><li>瓶颈由证据指认：逐轮时间线显示 TTFT 随会话增长、实喂 52% 是重复 prefill——改动选&quot;消重复&quot;而非执行优化；</li><li>一项通过一项撤回：v2 前缀复用（TTFT p95 −70.5%、实喂 −63%、总墙钟 −19.3%、质量不变、24/24 全同、结构契约断言全过；两次运行结论一致）采纳；v1 int8（质量 6/8 低于预算、总墙钟无稳定收益）如实撤回；组合继承失败不采纳——<strong>撤回与通过同样是有证据的结论</strong>；</li><li>正确性分三层：结构契约断言（cache_miss==0）、轨迹对照（24/24 全同；分叉先查输入序列再谈浮点——开发期教训）、任务预算判定（8/8）；</li><li>报告六要素齐备（入口/环境/原始测量/改动结果/适用范围/回退），开发期三轮调试过程如实保留——可复现性本身就是交付物。</li></ul><h2 id="本章出处" tabindex="-1">本章出处 <a class="header-anchor" href="#本章出处" aria-label="Permalink to &quot;本章出处&quot;">​</a></h2><p>负载与判据沿用第 5 章 8 样例质量预算；v2 机制为第 4 章前缀复用的会话级实例；v1 为第 5 章 int8 动态量化；模板行为（直答模式历史重渲染不含空 think 块）为本章实测直查。全部数字来自 <code>experiments/exp_ch16_capstone/raw.json</code>（含复跑命令与逐轮原始数据）。</p>`,33)])])}const u=o(s,[["render",d]]);export{c as __pageData,u as default};
